def transform(grid):
    out = [row[:] for row in grid]
    marker = next(c for c in range(len(grid[0])) if all(row[c] == 2 for row in grid))
    cells = [(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v not in (2,5)]
    if not cells:
        return out
    lo, hi = min(c for r,c in cells), max(c for r,c in cells)
    target = lo-1 if hi < marker else hi+1
    if 0 <= target < len(grid[0]):
        for r in range(len(grid)):
            out[r][target] = 8
    return out
